-- Mathematics: Arithmetic Foundations (English, subject 'math').
-- A mastery-based arithmetic course modeled on Khan Academy progression:
-- diagnostic first, short teaching cycles (objective, instruction, worked
-- examples, practice, misconceptions, exit ticket), checkpoints after each
-- unit cluster, and a cumulative final assessment. All content is original.
-- Fixed UUIDs and guarded inserts make the file idempotent: safe to re-run.

-- ============ Arithmetic Foundations ============
insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, subject, prerequisite_ids)
values (
  'bbbb0001-0000-4000-8000-000000000001',
  'en', null,
  'Arithmetic Foundations',
  'Build rock-solid arithmetic from place value to percentages and ratios. Every lesson teaches with worked examples, real-life practice problems, and exit tickets, with checkpoints along the way so you only move on once you have mastered the step before.',
